//
//  OperationCatalog.swift
//  GODOps
//
//  The operation reference, served to MCP clients on demand.
//
//  The Configuration Reference is the one place operations are documented,
//  so rather than describe them a second time in Swift it is embedded
//  verbatim (`OperationReference.markdown`, generated by
//  `scripts/gen_operation_reference.py`) and sliced here: the family section
//  that documents an operation, and the one-line summary from the marker
//  line that introduces it (`**`name`** *(flat)* — summary.`).
//  `OperationCatalogTests` keeps the embedded copy equal to the file and
//  checks that every `OperationName` has a marker to be found by.
//

import Foundation

public enum OperationCatalog {

    public struct Entry: Equatable {
        public let name: String
        /// `flat` or `container`, as the reference marks it.
        public let shape: String
        public let summary: String
    }

    // MARK: - What the tools serve

    /// Every operation, in `OperationName` order.
    public static var entries: [Entry] {
        OperationName.allCases.compactMap { entry(for: $0) }
    }

    /// Markdown naming every operation with its shape and summary — what
    /// `list_operations` returns.
    public static var listing: String {
        var lines = [
            "GODDESS operations. Call `describe_operation` with a name for its fields and example JSON, "
                + "then `run_operation` with `{ \"<name>\": { \"config\": { … } } }`.",
            "",
        ]
        for entry in entries {
            lines.append("- `\(entry.name)` *(\(entry.shape))* — \(entry.summary)")
        }
        return lines.joined(separator: "\n")
    }

    /// The reference section documenting `name`, followed by the JSON
    /// conventions every operation object follows — what
    /// `describe_operation` returns. Nil for a name that isn't an operation.
    public static func description(of name: String) -> String? {
        guard let operation = OperationName(rawValue: name),
              let section = section(for: operation) else { return nil }
        return section + "\n\n" + jsonConventions
    }

    // MARK: - Slicing the reference

    static var operationReference: String { chapter(titled: "## Operation reference") }

    static var jsonConventions: String { chapter(titled: "## JSON conventions") }

    /// The `### ` section of the operation reference that carries `name`'s
    /// marker, heading included.
    static func section(for name: OperationName) -> String? {
        sections(of: operationReference).first { $0.contains(marker(for: name)) }
    }

    /// Shape and summary, read off `name`'s marker line.
    static func entry(for name: OperationName) -> Entry? {
        guard let section = section(for: name) else { return nil }
        let lines = section.components(separatedBy: "\n")
        guard let index = lines.firstIndex(where: { $0.contains(marker(for: name)) }) else { return nil }

        let markerLine = lines[index]
        guard let shapeStart = markerLine.range(of: "*("),
              let shapeEnd = markerLine.range(of: ")*", range: shapeStart.upperBound ..< markerLine.endIndex),
              let dash = markerLine.range(of: " — ", range: shapeEnd.upperBound ..< markerLine.endIndex) else {
            return nil
        }
        var shape = String(markerLine[shapeStart.upperBound ..< shapeEnd.lowerBound])
        if shape == "containers" { shape = "container" }

        // The summary may wrap onto following lines; it ends at the first
        // sentence, or where a table, list, code block or the next marker
        // begins.
        var summary = String(markerLine[dash.upperBound...])
        var next = index + 1
        while !summary.contains(". "), !summary.hasSuffix("."), next < lines.count {
            let line = lines[next].trimmingCharacters(in: .whitespaces)
            if line.isEmpty || ["|", "-", "**", "```", "#"].contains(where: line.hasPrefix) { break }
            summary += " " + line
            next += 1
        }
        if let end = summary.range(of: ". ") {
            summary = String(summary[..<end.lowerBound]) + "."
        }
        return Entry(name: name.rawValue, shape: shape, summary: summary.trimmingCharacters(in: .whitespaces))
    }

    private static func marker(for name: OperationName) -> String {
        "**`\(name.rawValue)`**"
    }

    /// The text from `heading` up to the next heading of the same level.
    private static func chapter(titled heading: String) -> String {
        let lines = OperationReference.markdown.components(separatedBy: "\n")
        guard let start = lines.firstIndex(of: heading) else { return "" }
        let level = String(heading.prefix { $0 == "#" }) + " "
        let end = lines[(start + 1)...].firstIndex { $0.hasPrefix(level) } ?? lines.count
        return lines[start ..< end].joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines)
    }

    /// The `### ` sections of a chapter, each with its heading.
    private static func sections(of chapter: String) -> [String] {
        var sections: [[String]] = []
        for line in chapter.components(separatedBy: "\n") {
            if line.hasPrefix("### ") {
                sections.append([line])
            } else if !sections.isEmpty {
                sections[sections.count - 1].append(line)
            }
        }
        return sections.map { $0.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines) }
    }
}
